    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    int64 k, m;
    std::cin >> n >> k >> m;

    std::vector<int64> powerK(n);
    powerK[0] = 1 % k;
    for (int i = 1; i < n; ++i)
        powerK[i] = mulMod(powerK[i - 1], 10, k);

    std::vector<int64> powerM(n + 1);
    powerM[0] = 1 % m;
    for (int i = 1; i <= n; ++i)
        powerM[i] = mulMod(powerM[i - 1], 10, m);

    std::vector<int64> next(static_cast<std::size_t>(k), 0);
    std::vector<int64> current(static_cast<std::size_t>(k), 0);

    for (int position = n - 1; position >= 0; --position) {
        const int remaining = n - position;
        int64 ways;

        if (remaining == 1)
            ways = 1 % m;
        else if (remaining == 2)
            ways = 9 % m;
        else
            ways = mulMod(9, powerM[remaining - 2], m);

        for (int64 remainder = 0; remainder < k; ++remainder) {
            i128 sum = 0;

            for (int digit = 0; digit <= 9; ++digit) {
                const int64 newRemainder = static_cast<int64>(
                    (static_cast<i128>(digit) * powerK[position] + remainder) % k
                );

                if (newRemainder == 0 && digit != 0)
                    sum += ways;
                else if (position != n - 1)
                    sum += next[static_cast<std::size_t>(newRemainder)];
            }

