#include <iostream>
#include <vector>
#include <cstddef>

using int64 = long long;
using i128 = __int128_t;

int64 n, k, mod;
std::vector<int64> powerK;
std::vector<int64> memo;

int64 mulMod(int64 a, int64 b, int64 m) {
    return static_cast<int64>((static_cast<i128>(a) * b) % m);
}

int64 power10(int64 exponent, int64 m) {
    int64 result = 1 % m;
    int64 base = 10 % m;

    while (exponent > 0) {
        if (exponent & 1)
            result = mulMod(result, base, m);
        base = mulMod(base, base, m);
        exponent >>= 1;
    }
    return result;
}

int64 solve(int64 position, int digit, int64 remainder) {
    remainder = (remainder +
                 static_cast<int64>(
                     (static_cast<i128>(digit) * powerK[position]) % k)) % k;

    if (remainder == 0 && digit != 0) {
        int64 remaining = n - position;
        if (remaining == 1)
            return 1 % mod;
        return mulMod(9 % mod, power10(remaining - 2, mod), mod);
    }

    if (position == n - 1)
        return 0;

    std::size_t index =
        static_cast<std::size_t>(position) * static_cast<std::size_t>(k) +
        static_cast<std::size_t>(remainder);

    if (memo[index] != -1)
        return memo[index];

    int64 result = 0;
    for (int nextDigit = 0; nextDigit <= 9; ++nextDigit) {
        result = static_cast<int64>(
            (static_cast<i128>(result) +
             solve(position + 1, nextDigit, remainder)) % mod);
    }

    return memo[index] = result;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n >> k >> mod;

    powerK.resize(static_cast<std::size_t>(n));
    powerK[0] = 1 % k;
    for (int64 i = 1; i < n; ++i)
        powerK[i] = mulMod(powerK[i - 1], 10, k);

    memo.assign(static_cast<std::size_t>(n) * static_cast<std::size_t>(k), -1);

    int64 answer = 0;
    for (int digit = 0; digit <= 9; ++digit) {
        answer = static_cast<int64>(
            (static_cast<i128>(answer) + solve(0, digit, 0)) % mod);
    }

    std::cout << answer << '\n';
    return 0;
}

