#include <algorithm>

using int64 = long long;
using int128 = __int128_t;

int64 mulMod(int64 a, int64 b, int64 mod) {
    return static_cast<int64>(static_cast<int128>(a) * b % mod);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int64 n, k, m;
    std::cin >> n >> k >> m;

    if (n <= 0 || k <= 0 || m <= 0) {
        std::cout << 0 << '\n';
        return 0;
    }

    std::vector<int64> powers(static_cast<std::size_t>(n));
    powers[0] = 1 % k;
    for (int64 i = 1; i < n; ++i) {
        powers[static_cast<std::size_t>(i)] =
            mulMod(powers[static_cast<std::size_t>(i - 1)], 10, k);
    }

    std::vector<int64> next(static_cast<std::size_t>(k), 0);
    std::vector<int64> current(static_cast<std::size_t>(k), 0);

    int64 terminal = 0;

    for (int64 pos = n - 1; pos >= 0; --pos) {
        const int64 remaining = n - pos;

        if (remaining == 1)
            terminal = 1 % m;
        else if (remaining == 2)
            terminal = 9 % m;
        else
            terminal = mulMod(terminal, 10, m);

        std::fill(current.begin(), current.end(), 0);
        const int64 power = powers[static_cast<std::size_t>(pos)];

        for (int64 remainder = 0; remainder < k; ++remainder) {
            int64 total = 0;

            for (int digit = 0; digit <= 9; ++digit) {
                const int64 newRemainder = static_cast<int64>(
                    (static_cast<int128>(digit) * power + remainder) % k
                );

                const int64 value =
                    (newRemainder == 0 && digit != 0)
                        ? terminal
                        : next[static_cast<std::size_t>(newRemainder)];

                total = static_cast<int64>(
                    (static_cast<int128>(total) + value) % m
                );
            }

            current[static_cast<std::size_t>(remainder)] = total;
        }

        next.swap(current);
    }

    std::cout << next[0] % m << '\n';
    return 0;
}

